     3  const renderGalleryScript = `
     4    const React = (await import('react')).default
     5    const { renderToStaticMarkup } = await import('react-dom/server')
     6    const { NotionRenderer } = await import('react-notion-x')
     7    const { Collection } = await import('react-notion-x/build/third-party/collection')
     8    const createRecordMap = showPageIcon => ({
     9      block: {
    10        collection_view: {
    11          value: { id: 'collection_view', type: 'collection_view',
    12            collection_id: 'collection', view_ids: ['gallery_view'] }
    13        },
    14        page: {
    15          value: { id: 'page', type: 'page', parent_table: 'collection',
    16            properties: { title: [['Gallery item']] },
    17            format: { page_icon: '📄' } }
    18        }
    19      },
    20      collection: {
    21        collection: {
    22          value: { id: 'collection', name: [['Gallery']],
    23            schema: { title: { name: 'Name', type: 'title' } } }
    24        }
    25      },
    26      collection_view: {
    27        gallery_view: {
    28          value: { id: 'gallery_view', type: 'gallery',
    29            format: {
    30              collection_pointer: { id: 'collection' },
    31              show_page_icon: showPageIcon,
    32              gallery_cover: { type: 'none' },
    33              gallery_cover_size: 'medium',
    34              gallery_cover_aspect: 'cover',
    35              gallery_properties: []
    36            } }
    37        }
    38      },
    39      collection_query: {
    40        collection: {
    41          gallery_view: { collection_group_results: { blockIds: ['page'] } }
    42        }
    43      },
    44      signed_urls: {}
    45    })
    46    const renderGallery = showPageIcon =>
    47      renderToStaticMarkup(
    48        React.createElement(NotionRenderer, {
    49          recordMap: createRecordMap(showPageIcon),
    50          components: { Collection }
    51        })
    52      )
    53    process.stdout.write(JSON.stringify({
    54      hidden: renderGallery(false),
    55      visible: renderGallery(true)
    56    }))
    57  `
    58  
    59  describe('Notion Gallery page icon setting', () => {
    60    const result = JSON.parse(
    61      execFileSync(process.execPath, [
    62        '--input-type=module',
    63        '-e',
    64        renderGalleryScript
    65      ])
    66    )
    67  
    68    it('adds the page-icon hiding class when Notion disables icons', () => {
    69      expect(result.hidden).toContain(
    70        'notion-gallery notion-gallery-hide-page-icons'
    71      )
    72    })
    73  
    74    it('keeps page icons visible when Notion enables icons', () => {
    75      expect(result.visible).toContain('class="notion-gallery"')
    76      expect(result.visible).not.toContain('notion-gallery-hide-page-icons')
    77    })
    78  })
